import {HEROES,PART_NAMES,hydrate,serialize} from './engine.js';
import {QA_SCENARIOS,qaFixture,qaApplyCondition} from './qa-fixtures.js';
import {feedbackEntry,feedbackDocument,importFeedback,mergeFeedback} from './qa-feedback.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),STORE='teyvat-embers-qa-feedback-v1',DRAFT='teyvat-embers-qa-draft-v1',frame=$('#game-preview');
let gameState=null,context=null,entries=[],editId=null,gameBusy=false;
const status=text=>$('#feedback-status').textContent=text;
function store(){try{localStorage.setItem(STORE,JSON.stringify(entries));}catch{status('피드백 자동 저장이 실패했습니다. JSON으로 내보내주세요.');}}
function draft(){return {title:$('#feedback-title').value,actual:$('#actual').value,expected:$('#expected').value,category:$('#category').value,priority:$('#priority').value,includeSave:$('#include-save').checked};}
function restoreDraft(d){if(!d)return;for(const [id,key] of [['feedback-title','title'],['actual','actual'],['expected','expected'],['category','category'],['priority','priority']])if(typeof d[key]==='string')$('#'+id).value=d[key];$('#include-save').checked=d.includeSave!==false;}
function saveDraft(){try{localStorage.setItem(DRAFT,JSON.stringify(draft()));}catch{status('작성 중인 내용은 JSON 내보내기로 보존해주세요.');}}
try{entries=importFeedback(JSON.stringify({schema:'teyvat-embers-feedback-v1',entries:JSON.parse(localStorage.getItem(STORE)||'[]')})).entries;restoreDraft(JSON.parse(localStorage.getItem(DRAFT)||'null'));}catch{status('이전에 작성한 기록을 읽지 못했습니다. JSON이 있다면 불러와 주세요.');}
$('#scenario').innerHTML=Object.entries(QA_SCENARIOS).map(([id,name])=>`<option value="${id}">${name}</option>`).join('');
for(const id of ['hero','companion1','companion2'])$('#'+id).innerHTML=Object.entries(HEROES).filter(([k])=>id==='hero'||k!=='lohen').map(([k,h])=>`<option value="${k}">${h.name}</option>`).join('');$('#companion1').value='durin';$('#companion2').value='illuga';
function send(type,data={}){if(gameBusy){status('연출이 끝난 뒤 다시 눌러주세요.');return;}frame.contentWindow.postMessage({source:'embers-qa-controls',type,...data},location.origin);}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.source!=='embers-game-qa')return;if(e.data.error){status(e.data.error);return;}if(!e.data.state)return;try{gameState=hydrate(e.data.state);for(const id of ['load-scenario','apply-condition','preview'])$('#'+id).disabled=false;gameBusy=!!e.data.busy;context={scenario:$('#scenario').value,phase:gameState.phase,node:gameState.node,party:gameState.party,turn:gameState.battle?.turn||null,width:frame.clientWidth,height:frame.clientHeight,hero:$('#hero').value};$('#game-context').textContent=`${gameState.phase} · ${gameState.party.map(id=>HEROES[id].name).join(' / ')}${context.turn?' · '+context.turn+'턴':''}`;}catch{status('테스트 상태를 읽지 못했습니다.');}});
$('#load-scenario').onclick=()=>{try{send('load',{state:qaFixture($('#scenario').value,{hero:$('#hero').value,pair:[$('#companion1').value,$('#companion2').value],breakdown:$('#breakdown').value||'despair',failures:$('#failures').value})});status('선택한 테스트 장면을 불러왔습니다.');}catch(e){status(e.message);}};
$('#apply-condition').onclick=()=>{try{if(!gameState)throw Error('게임이 연결된 뒤 사용하세요.');send('load',{animate:$('#animate-condition').checked,state:qaApplyCondition(gameState,{hero:$('#hero').value,part:$('#part').value,stage:$('#stage').value,breakdown:$('#breakdown').value,failures:$('#failures').value,ap:$('#ap').value,support:$('#support').value,scar:$('#scar').value})});status('선택한 전투원의 상태를 적용했습니다.');}catch(e){status(e.message);}};
$('#preview').onclick=()=>send('preview',{hero:$('#hero').value,kind:$('#preview-kind').value,hold:$('#hold-vfx').checked,collapseStage:$('#collapse-stage').value});$('#resume').onclick=()=>send('resume');
$('#viewport-size').onchange=()=>{const size={desktop:[1280,720],landscape:[844,390],compact:[640,360],portrait:[390,740]}[$('#viewport-size').value];frame.style.width=size?size[0]+'px':'100%';frame.style.height=size?size[1]+'px':'580px';if(context){context.width=size?.[0]||frame.clientWidth;context.height=size?.[1]||frame.clientHeight;}};
function renderEntries(){$('#feedback-list').innerHTML=entries.length?[...entries].reverse().map(e=>`<article class="feedback-item ${e.status==='resolved'?'feedback-done':''}" data-id="${esc(e.id)}"><small>${esc(e.category)} · ${esc(e.context?.phase||'장면 없음')} · ${esc(e.context?.width||'?')}×${esc(e.context?.height||'?')} · ${esc(e.createdAt.slice(0,16).replace('T',' '))}</small><h3><span class="feedback-tag ${esc(e.priority)}">${({normal:'보통',high:'높음',blocker:'진행 불가',idea:'제안'})[e.priority]}</span> ${esc(e.title)}</h3><p>${esc(e.actual)}</p>${e.expected?`<p><b>원하는 모습</b><br>${esc(e.expected)}</p>`:''}<small>${e.save?'테스트 상태 첨부됨':'상태 첨부 없음'} · ${e.status==='resolved'?'확인 완료':'미검토'}</small><div class="item-actions"><button data-fb="edit">수정</button><button data-fb="resolved">${e.status==='resolved'?'미검토로':'확인 완료로'}</button>${e.save?'<button data-fb="reproduce">이 상태 재현</button>':''}<button data-fb="remove">기록 지우기</button></div></article>`).join(''):'<p class="hint">아직 기록이 없습니다. 위 양식으로 첫 피드백을 남겨주세요.</p>';}
function resetForm(){editId=null;$('#feedback-form').reset();$('#save-feedback').textContent='피드백 추가';$('#cancel-edit').hidden=true;saveDraft();}
$('#feedback-form').addEventListener('input',saveDraft);$('#feedback-form').onsubmit=e=>{e.preventDefault();try{const old=entries.find(x=>x.id===editId),fields={...draft(),id:editId,createdAt:old?.createdAt,status:old?.status};const entry=feedbackEntry(fields,old?.context||context,old?.save||gameState);if(editId)entries=entries.map(x=>x.id===editId?entry:x);else entries.push(entry);store();renderEntries();resetForm();status('피드백을 저장했습니다. JSON으로 내보내 채팅에 첨부할 수 있습니다.');}catch(e){status(e.message);}};$('#cancel-edit').onclick=resetForm;
$('#feedback-list').onclick=e=>{const action=e.target.closest('[data-fb]'),row=action?.closest('[data-id]'),entry=entries.find(x=>x.id===row?.dataset.id);if(!entry)return;switch(action.dataset.fb){case'edit':editId=entry.id;restoreDraft({...entry,includeSave:!!entry.save});$('#save-feedback').textContent='수정 저장';$('#cancel-edit').hidden=false;$('#feedback-title').focus();break;case'resolved':entry.status=entry.status==='resolved'?'open':'resolved';entry.updatedAt=new Date().toISOString();store();renderEntries();break;case'reproduce':try{if(QA_SCENARIOS[entry.context?.scenario])$('#scenario').value=entry.context.scenario;send('load',{state:hydrate(entry.save)});status('첨부된 테스트 상태를 불러왔습니다.');}catch{status('첨부된 저장 상태를 불러올 수 없습니다.');}break;case'remove':entries=entries.filter(x=>x.id!==entry.id);store();renderEntries();status('기록을 지웠습니다. 내보낸 JSON이 있으면 다시 불러올 수 있습니다.');break;}};
$('#export-feedback').onclick=()=>{const content=JSON.stringify(feedbackDocument(entries,draft()),null,2),url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`teyvat-embers-feedback-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('피드백과 작성 중인 내용을 JSON으로 내보냈습니다.');};
$('#import-feedback').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>15*1024*1024)throw Error('15MB 이하의 피드백 JSON을 선택하세요.');const data=importFeedback(await file.text());entries=mergeFeedback(entries,data.entries);store();if(data.draft)restoreDraft(data.draft);saveDraft();renderEntries();status(`${data.entries.length}개 기록을 불러왔습니다. 같은 기록은 최신 수정본을 유지합니다.`);}catch(e){status(e.message);}e.target.value='';};renderEntries();

$('#stop-preview').onclick=()=>send('stopPreview');
